CREATE TABLE "user" ("id" text PRIMARY KEY, "name" text NOT NULL, "email" text NOT NULL, "email_verified" boolean DEFAULT false NOT NULL, "image" text, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "user_email_idx" ON "user" ("email");
CREATE TABLE "session" ("id" text PRIMARY KEY, "expires_at" timestamptz NOT NULL, "token" text NOT NULL, "ip_address" text, "user_agent" text, "user_id" text NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "session_token_idx" ON "session" ("token"); CREATE INDEX "session_user_idx" ON "session" ("user_id");
CREATE TABLE "account" ("id" text PRIMARY KEY, "account_id" text NOT NULL, "provider_id" text NOT NULL, "user_id" text NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "access_token" text, "refresh_token" text, "id_token" text, "access_token_expires_at" timestamptz, "refresh_token_expires_at" timestamptz, "scope" text, "password" text, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "account_provider_identity_idx" ON "account" ("provider_id","account_id"); CREATE INDEX "account_user_idx" ON "account" ("user_id");
CREATE TABLE "verification" ("id" text PRIMARY KEY, "identifier" text NOT NULL, "value" text NOT NULL, "expires_at" timestamptz NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL); CREATE INDEX "verification_identifier_idx" ON "verification" ("identifier");
CREATE TABLE "project" ("id" text PRIMARY KEY, "name" text NOT NULL, "description" text, "owner_id" text NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL); CREATE INDEX "project_owner_updated_idx" ON "project" ("owner_id","updated_at");
